it.each(modes)('uses actual mTLS and native focus for guided secret ownership: %s',async mode=>{
  // Disposable observation only: no timer, budget, policy, assertion or product-source change.
  type TimingScalar=number|boolean|BridgeStop['reason']|null;
  const timingFields={
    'schedule-enter':['nextRenewalWallMs','secretContext'],
    'schedule-return':['nextRenewalWallMs','secretContext'],
    'request-claim-enter':['initial','nextRenewalWallMs','secretContext'],
    'request-claim-sync-return':['initial'],
    'grant-validated':['initial','stopped'],
    'invalidate-enter':['stopped'],
    'invalidate-return':['stopped'],
    'stop-entry':['reason','alreadyStopped'],
    'runtime-stop-enter':['reason','stopped'],
    'runtime-post-stop-observer':['reason','stopped','observedMonoMs','observedWallMs'],
    'claim-port-enter':['timeoutMs','aborted'],
    'claim-abort-event':['timeoutMs','aborted'],
    'complete-ack':['lastAckT0MonoMs','focusSeen'],
    'claim-rejected':['timeoutMs'],
  } as const;
  type TimingEvent=keyof typeof timingFields;
  const timingRows:{event:TimingEvent;monoMs:number;wallMs:number;observerEndMonoMs:number;fields:Readonly<Record<string,TimingScalar>>}[]=[];
  const timingReasons=new Set<string>(['CANCELLED','EXPIRED','UNKNOWN_OUTCOME','LEASE_LOST','CONTEXT_LOST','REVOKED']);
  const timingAbortListeners:{signal:AbortSignal;listener:()=>void}[]=[];
  let timingOverflow=false,timingIncomplete=false,timingCleanupComplete=false,timingMocksRestored=false;
  const observeTiming=(event:TimingEvent,fields:Readonly<Record<string,TimingScalar>>):void=>{
    try{
      const monoMs=performance.now(),wallMs=Date.now();
      if(timingRows.length>=64){timingOverflow=true;return;}
      const allowed:readonly string[]=timingFields[event];
      if(Object.keys(fields).length!==allowed.length||Object.entries(fields).some(([key,value])=>!allowed.includes(key)||!(value===null||typeof value==='boolean'||typeof value==='number'&&Number.isFinite(value)||typeof value==='string'&&key==='reason'&&timingReasons.has(value)))){timingIncomplete=true;return;}
      const row={event,monoMs,wallMs,observerEndMonoMs:0,fields};timingRows.push(row);row.observerEndMonoMs=performance.now();
    }catch{timingIncomplete=true;}
  };
  type TimingEntry={readonly stopped:boolean;readonly nextRenewal?:number;readonly runtime:GuidedRuntime|null};
  type TimingOwnership={
    schedule(entry:TimingEntry):void;
    requestClaim(entry:TimingEntry,initial:boolean):Promise<unknown>;
    checkGrant(entry:TimingEntry,value:unknown,initial:boolean):unknown;
    invalidate(entry:TimingEntry):void;
    stopEntry(entry:TimingEntry,reason:BridgeStop['reason']):Promise<void>;
  };
  const timingPrototype=GuidedOwnership.prototype as unknown as TimingOwnership;

try{
  // Each descriptor wrapper calls the original once, with the same receiver/arguments and exact return value/promise.
  try{
    const original=Object.getOwnPropertyDescriptor(GuidedOwnership.prototype,'schedule')?.value as TimingOwnership['schedule']|undefined;
    if(typeof original!=='function')timingIncomplete=true;
    else vi.spyOn(timingPrototype,'schedule').mockImplementation(function(this:GuidedOwnership,entry){
      observeTiming('schedule-enter',{nextRenewalWallMs:entry.nextRenewal??null,secretContext:entry.runtime?.hasSecretInputs===true});
      const returned=original.call(this,entry);
      observeTiming('schedule-return',{nextRenewalWallMs:entry.nextRenewal??null,secretContext:entry.runtime?.hasSecretInputs===true});return returned;
    });
    const request=Object.getOwnPropertyDescriptor(GuidedOwnership.prototype,'requestClaim')?.value as TimingOwnership['requestClaim']|undefined;
    if(typeof request!=='function')timingIncomplete=true;
    else vi.spyOn(timingPrototype,'requestClaim').mockImplementation(function(this:GuidedOwnership,entry,initial){
      observeTiming('request-claim-enter',{initial,nextRenewalWallMs:entry.nextRenewal??null,secretContext:entry.runtime?.hasSecretInputs===true});
      const returned=request.call(this,entry,initial);observeTiming('request-claim-sync-return',{initial});return returned;
    });
    const checked=Object.getOwnPropertyDescriptor(GuidedOwnership.prototype,'checkGrant')?.value as TimingOwnership['checkGrant']|undefined;
    if(typeof checked!=='function')timingIncomplete=true;
    else vi.spyOn(timingPrototype,'checkGrant').mockImplementation(function(this:GuidedOwnership,entry,value,initial){
      const returned=checked.call(this,entry,value,initial);observeTiming('grant-validated',{initial,stopped:entry.stopped});return returned;
    });
    const invalidated=Object.getOwnPropertyDescriptor(GuidedOwnership.prototype,'invalidate')?.value as TimingOwnership['invalidate']|undefined;
    if(typeof invalidated!=='function')timingIncomplete=true;
    else vi.spyOn(timingPrototype,'invalidate').mockImplementation(function(this:GuidedOwnership,entry){
      observeTiming('invalidate-enter',{stopped:entry.stopped});const returned=invalidated.call(this,entry);observeTiming('invalidate-return',{stopped:entry.stopped});return returned;
    });
    const stopped=Object.getOwnPropertyDescriptor(GuidedOwnership.prototype,'stopEntry')?.value as TimingOwnership['stopEntry']|undefined;
    if(typeof stopped!=='function')timingIncomplete=true;
    else vi.spyOn(timingPrototype,'stopEntry').mockImplementation(function(this:GuidedOwnership,entry,reason){
      observeTiming('stop-entry',{reason,alreadyStopped:entry.stopped});return stopped.call(this,entry,reason);
    });
  }catch{timingIncomplete=true;}
  expect((await post(address.port,path+'/assign'

    }finally{
      for(const {signal,listener} of timingAbortListeners){try{signal.removeEventListener('abort',listener);}catch{timingIncomplete=true;}}
      if(!timingMocksRestored){try{vi.restoreAllMocks();timingMocksRestored=true;}catch{timingIncomplete=true;}}
      // A missing/failed flush is incomplete diagnostic evidence, never a replacement test error.
      try{await writeFile(resolve('../docs/qa/evidence/STUDIO-OBS-007/runner-guided-renew-execution-2/ownership-timing-diagnostic.json'),JSON.stringify({schemaVersion:1,selectedCaseWasLostBodyLateGrant:mode==='lost-body-late-grant',capacity:64,overflow:timingOverflow,instrumentationFailed:timingIncomplete,originalCleanupComplete:timingCleanupComplete,mocksRestored:timingMocksRestored,records:timingRows},null,2)+'\n');}catch{/* Missing closed output invalidates the diagnostic; preserve the original test result. */}
    }
  }
},45000);
